head.script:
scwin.draw = function() {
    var options = {
        "caption": "Half Yearly Revenue Analysis",
        "ayaxisname": "Revenue", //웹접근성 y축 값 
        "axaxisname": "Year", //웹접근성 x축 값
    };
    chart_test_flash.setChartAttribute(options);
    chart_test_flash.setJSONData(dataObj);
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "2000");	
    WebSquare.wUnit.addCommand("assert", "accessibility_mf_chart_test_flash.childNodes[2].childNodes[0].childNodes[0].innerText == 'Jul'", "true");
    WebSquare.wUnit.addCommand("assert", "accessibility_mf_chart_test_flash.childNodes[1].tagName == 'THEAD'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.dataObj = {
        "chart": {},
        "data": [{
                "label": "Jul",
                "value": "150000"
            },
            {
                "label": "Aug",
                "value": "130000"
            },
            {
                "label": "Sep",
                "value": "95000"
            },
            {
                "label": "Oct",
                "value": "170000"
            },
            {
                "label": "Nov",
                "value": "155000"
            },
            {
                "label": "Dec",
                "value": "230000"
            }
        ]
    };
    scwin.draw();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Mar-2018
    //End unitTest
}
